import { attio } from adapters
crm = attio()
kg = attio()
rules = "the rules"
import { Pitch, Plain as P2 } from "deals"
import { Wide } from "more"
type Stage = <"Seed" | "Series A" | "Late">
movement m(msg: <crm-[:company]->>) {
  found = extract from [msg.`name`] through [vc_url_retrieval] {
    value: "the name"
    `Ünï`: <Stage | null> "pick from ${rules}"
      node entry: "each one, if any" {
        when: <boolean> "${UPPER(rules)} and more"
      }
      node `Big Co`: <Pitch>
  } through [vc_url_retrieval] {
    when: <boolean> "a tab\there"
    website: "${UPPER(rules)} and more"
      node note: <P2> through [vc_url_retrieval, fetch_url(url: website)] {
      }
  } through [vc_url_retrieval] {
    summary: "a tab\there"
    `Ünï`: <number> "pick from ${rules}"
  }
}

